@PostMapping(value = "login")
    public GenericRpcResponse<MerchantTokenDTO> login(@RequestBody MerchantLoginDTO merchantLoginDTO) {
        MerchantTokenDTO merchantTokenDTO = merchantService.login(merchantLoginDTO);
        if (isNull(merchantTokenDTO)) {
            throw new EclipseRuntimeException("用户不存在",ErrorEnum.NO_FOUND_USER.getErrorCode());
        }

        return GenericRpcResponse.success(merchantTokenDTO);
    }

@Override
    public boolean saveUser(UserVO userVO) {
        UserDO record = new UserDO();
        record.setUserId(Long.valueOf(userVO.getUserId()));
        record.setNickName(userVO.getNickname());
        record.setAvatar(userVO.getAvatar());
        setDefaultValue(record);
        return userMapper.insert(record) == 1;
    }

