@Override
    public boolean updateUserInfo(UserInfoVO userInfoVO) {
        UserInfoDO record = convertUserInfoDO(userInfoVO);
        setDefaultValue(record);
        return userInfoMapper.updateByPrimaryKey(record) == 1;
    }

private UserInfoDO convertUserInfoDO(UserInfoVO userInfoVO) {
        UserInfoDO userInfoDO = new UserInfoDO();
        if (userInfoVO.getId() != null) {
            userInfoDO.setId(Long.valueOf(userInfoVO.getId()));
        }
        if (userInfoVO.getUserId() != null) {
            userInfoDO.setUserId(Long.valueOf(userInfoVO.getUserId()));
        }
        if (userInfoVO.getBirthday() != null) {
            userInfoDO.setBirthDt(DateUtils.string2date(userInfoVO.getBirthday()));
        }
        if(userInfoVO.getCertificationDate() != null){
            userInfoDO.setCertificationDate(DateUtils.strToDateLong(userInfoVO.getCertificationDate()));
        }
        if(userInfoVO.getCertificationExpireDate() != null){
            userInfoDO.setCertificationExpireDate(DateUtils.strToDateLong(userInfoVO.getCertificationExpireDate()));
        }
        userInfoDO.setAppCode(userInfoVO.getAppCode());
        userInfoDO.setName(userInfoVO.getName());
        userInfoDO.setEmail(userInfoVO.getEmail());
        userInfoDO.setPhone(userInfoVO.getPhone());
        userInfoDO.setRelationCd(userInfoVO.getRelationType());
        userInfoDO.setPartyType(userInfoVO.getPartyType());
        userInfoDO.setCertNo(userInfoVO.getCertNo());
        userInfoDO.setCertTypeCd(userInfoVO.getCertType());
        userInfoDO.setGenderCd(userInfoVO.getGender());
        if(userInfoVO.getUserNickName() != null) {
            userInfoDO.setName(userInfoVO.getUserNickName());
        }
        if(userInfoVO.getUserAvatar()!= null) {
            userInfoDO.setAvatar(userInfoVO.getUserAvatar());
        }
//        userInfoDO.setCertifie();
        userInfoDO.setExtendInfo(CommonConverter.getDataToString(userInfoVO.getExtendInfo()));
        return userInfoDO;
    }

private void setDefaultValue(BaseDO baseDO) {
        baseDO.setValid(ValidUtil.getEffective());
        baseDO.setGmtCreate(new Date());
        baseDO.setGmtModified(baseDO.getGmtCreate());
    }
